import java.util.Arrays;
import java.util.Random;
import java.util.concurrent.atomic.AtomicLong;

public class ShortCode {
    static final String ALPHABET =
        "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";

    static String encode(long n) {
        if (n == 0) return "0";
        StringBuilder sb = new StringBuilder();
        while (n > 0) {
            sb.append(ALPHABET.charAt((int) (n % 62)));
            n /= 62;
        }
        return sb.reverse().toString();
    }

    static long decode(String s) {
        long n = 0;
        for (char c : s.toCharArray()) n = n * 62 + ALPHABET.indexOf(c);
        return n;
    }

    /** Feistel permutation over [0, 2^40) so that sequential ids give non-guessable codes. */
    static long permute(long x) {
        long l = x >>> 20, r = x & 0xFFFFF;
        for (int round = 0; round < 4; round++) {
            long f = ((r * 0x9E3779B1L + round * 0x85EBCA6BL) ^ (r >>> 7)) & 0xFFFFF;
            long nl = r, nr = l ^ f;
            l = nl;
            r = nr;
        }
        return (l << 20) | r;
    }

    /** Hands out id ranges the way a counter service would; each app server consumes a range. */
    static class RangeAllocator {
        private final AtomicLong next = new AtomicLong(1);
        long[] lease(int size) {
            long start = next.getAndAdd(size);
            return new long[] {start, start + size - 1};
        }
    }

    static int collisions(int bits, int n, long seed) {
        Random rnd = new Random(seed);
        long space = 1;
        for (int i = 0; i < bits; i++) space *= 62;
        long[] v = new long[n];
        for (int i = 0; i < n; i++) v[i] = Math.floorMod(rnd.nextLong(), space);
        Arrays.sort(v);
        int c = 0;
        for (int i = 1; i < n; i++) if (v[i] == v[i - 1]) c++;
        return c;
    }

    public static void main(String[] args) {
        for (long n : new long[] {0, 61, 62, 3844, 1_000_000_000L, 3_521_614_606_207L}) {
            String s = encode(n);
            System.out.printf("%16d -> %-8s -> %d%n", n, s, decode(s));
        }
        System.out.println("62^6 = " + (long) Math.pow(62, 6)
            + ", 62^7 = " + (long) Math.pow(62, 7));
        RangeAllocator ra = new RangeAllocator();
        for (int i = 1; i <= 3; i++) {
            long[] r = ra.lease(1000);
            System.out.println("app server " + i + " leases [" + r[0] + ", " + r[1] + "]");
        }
        System.out.println("sequential ids 1000001..1000004 -> plain / permuted");
        for (long id = 1_000_001; id <= 1_000_004; id++) {
            System.out.println("  " + encode(id) + "  /  " + encode(permute(id)));
        }
        java.util.Set<Long> outs = new java.util.HashSet<>();
        for (long id = 0; id < 1_000_000; id++) outs.add(permute(id));
        System.out.println("1,000,000 sequential ids -> distinct permuted values: " + outs.size());
        System.out.println("hash-truncation simulation (random values, fixed seed):");
        System.out.printf("  5 chars (9.2e8 space), 100000 codes: %d collisions%n",
                          collisions(5, 100_000, 7));
        System.out.printf("  7 chars (3.5e12 space), 5000000 codes: %d collisions%n",
                          collisions(7, 5_000_000, 7));
        System.out.printf("  expected (n^2 / 2S): %.1f and %.1f%n",
            1e10 / (2 * 916_132_832.0), 25e12 / (2 * 3_521_614_606_208.0));
    }
}

