import java.util.ArrayDeque;
import java.util.Deque;

public class RateLimit {
    interface Limiter { boolean allow(long nowMs); }

    /** Fixed window: count per aligned window. */
    static class FixedWindow implements Limiter {
        final int limit; final long windowMs; long windowStart = -1; int count;
        FixedWindow(int limit, long windowMs) { this.limit = limit; this.windowMs = windowMs; }
        public boolean allow(long now) {
            long ws = now - now % windowMs;
            if (ws != windowStart) { windowStart = ws; count = 0; }
            return count < limit && ++count > 0;
        }
    }

    /** Sliding window log: exact, stores one timestamp per accepted request. */
    static class SlidingLog implements Limiter {
        final int limit; final long windowMs; final Deque<Long> log = new ArrayDeque<>();
        SlidingLog(int limit, long windowMs) { this.limit = limit; this.windowMs = windowMs; }
        public boolean allow(long now) {
            while (!log.isEmpty() && log.peekFirst() <= now - windowMs) log.pollFirst();
            if (log.size() >= limit) return false;
            log.addLast(now);
            return true;
        }
    }

    /** Sliding window counter: weighted sum of previous and current fixed windows. */
    static class SlidingCounter implements Limiter {
        final int limit; final long windowMs; long curStart = -1; int cur, prev;
        SlidingCounter(int limit, long windowMs) { this.limit = limit; this.windowMs = windowMs; }
        public boolean allow(long now) {
            long ws = now - now % windowMs;
            if (ws != curStart) {
                prev = (ws - curStart == windowMs) ? cur : 0;
                cur = 0; curStart = ws;
            }
            double weight = 1.0 - (now - ws) / (double) windowMs;
            double estimate = prev * weight + cur;
            if (estimate >= limit) return false;
            cur++;
            return true;
        }
    }

    /** Token bucket: capacity tokens, refilled at ratePerSec; tokens kept as a double. */
    static class TokenBucket implements Limiter {
        final double capacity, ratePerSec; double tokens; long last = -1;
        TokenBucket(double capacity, double ratePerSec) {
            this.capacity = capacity; this.ratePerSec = ratePerSec; this.tokens = capacity;
        }
        public boolean allow(long now) {
            if (last >= 0) tokens = Math.min(capacity, tokens + (now - last) / 1000.0 * ratePerSec);
            last = now;
            if (tokens < 1) return false;
            tokens -= 1;
            return true;
        }
    }

    static int run(Limiter l, long[] times) {
        int ok = 0;
        for (long t : times) if (l.allow(t)) ok++;
        return ok;
    }

    public static void main(String[] args) {
        // limit: 10 requests per 10 s. Client sends 10 requests in the last 500 ms of window 0
        // and 10 requests in the first 500 ms of window 1 (times in ms).
        long[] burst = new long[20];
        for (int i = 0; i < 10; i++) { burst[i] = 9_500 + i * 50; burst[10 + i] = 10_000 + i * 50; }
        System.out.println("burst of 20 requests across a window boundary, limit 10 per 10 s");
        System.out.println("  fixed window   accepted: " + run(new FixedWindow(10, 10_000), burst));
        System.out.println("  sliding log    accepted: " + run(new SlidingLog(10, 10_000), burst));
        System.out.println("  sliding counter accepted: "
            + run(new SlidingCounter(10, 10_000), burst));
        System.out.println("  token bucket   accepted: " + run(new TokenBucket(10, 1.0), burst));

        // steady 5 req/s for 60 s, then idle 20 s, then a burst of 30 requests within 100 ms
        TokenBucket tb = new TokenBucket(20, 5.0);
        int okSteady = 0;
        for (long t = 0; t < 60_000; t += 200) if (tb.allow(t)) okSteady++;
        int okBurst = 0;
        for (int i = 0; i < 30; i++) if (tb.allow(80_000 + i * 3)) okBurst++;
        System.out.println("token bucket (capacity 20, 5/s): steady accepted " + okSteady
            + " of 300, burst after idle accepted " + okBurst + " of 30");

        // centralised vs per-node split limit: global limit 90/s, 3 nodes, 80% of traffic on node 0
        int total = 90, nodes = 3;
        int[] offered = {80, 10, 10};
        int central = Math.min(total, offered[0] + offered[1] + offered[2]);
        int local = 0;
        for (int n = 0; n < nodes; n++) local += Math.min(offered[n], total / nodes);
        System.out.println("global limit 90/s, offered 80+10+10 = 100/s");
        System.out.println("  central counter accepts " + central + "/s");
        System.out.println("  3 local limiters of 30/s accept " + local
            + "/s (the limit allows 90/s)");
    }
}

import java.util.concurrent.CountDownLatch;
import java.util.concurrent.atomic.AtomicInteger;

public class RaceDemo {
    static final int LIMIT = 100, THREADS = 8, ATTEMPTS_PER_THREAD = 500;

    interface Counter { boolean tryAcquire(); }

    /** Read-modify-write in two steps: what GET followed by SET does against a shared store. */
    static class CheckThenSet implements Counter {
        private volatile int count = 0;
        public boolean tryAcquire() {
            int c = count;                 // read
            if (c >= LIMIT) return false;
            java.util.concurrent.locks.LockSupport.parkNanos(20_000);  // stands in for a round trip
            count = c + 1;                 // write based on a stale read
            return true;
        }
    }

    /** Single atomic step: what a Lua script or INCR with a check provides. */
    static class Atomic implements Counter {
        private final AtomicInteger count = new AtomicInteger();
        public boolean tryAcquire() {
            while (true) {
                int c = count.get();
                if (c >= LIMIT) return false;
                if (count.compareAndSet(c, c + 1)) return true;
            }
        }
    }

    static int run(Counter counter) throws InterruptedException {
        AtomicInteger admitted = new AtomicInteger();
        CountDownLatch start = new CountDownLatch(1);
        Thread[] ts = new Thread[THREADS];
        for (int i = 0; i < THREADS; i++) {
            ts[i] = new Thread(() -> {
                try { start.await(); } catch (InterruptedException e) { return; }
                for (int k = 0; k < ATTEMPTS_PER_THREAD; k++) {
                    if (counter.tryAcquire()) admitted.incrementAndGet();
                }
            });
            ts[i].start();
        }
        start.countDown();
        for (Thread t : ts) t.join();
        return admitted.get();
    }

    public static void main(String[] args) throws Exception {
        System.out.println("limit = " + LIMIT + ", " + THREADS * ATTEMPTS_PER_THREAD + " attempts");
        for (int round = 1; round <= 3; round++) {
            int racy = run(new CheckThenSet());
            int safe = run(new Atomic());
            System.out.println("round " + round + ": check-then-set admitted " + racy
                + ", atomic admitted " + safe);
        }
    }
}

import java.util.concurrent.atomic.AtomicLong;
import java.util.function.LongSupplier;

public class IdGen {
    static final long EPOCH = 1_700_000_000_000L;   // custom epoch, ms
    static final int WORKER_BITS = 10, SEQ_BITS = 12;
    static final long MAX_SEQ = (1L << SEQ_BITS) - 1;

    /** Snowflake-style generator: 41 bits time | 10 bits worker | 12 bits sequence. */
    static class Snowflake {
        final long worker; final LongSupplier clock;
        long lastMs = -1, seq = 0; long waits = 0, rollbacks = 0;
        Snowflake(long worker, LongSupplier clock) { this.worker = worker; this.clock = clock; }

        synchronized long next() {
            long now = clock.getAsLong();
            if (now < lastMs) {                       // clock moved backwards
                rollbacks++;
                if (lastMs - now > 5) throw new IllegalStateException(
                    "clock moved back " + (lastMs - now) + " ms, refusing to generate");
                now = lastMs;                         // tolerate a small step: stay on lastMs
            }
            if (now == lastMs) {
                seq = (seq + 1) & MAX_SEQ;
                if (seq == 0) {                       // 4096 ids used in this millisecond
                    waits++;
                    while (now <= lastMs) now = clock.getAsLong();
                }
            } else {
                seq = 0;
            }
            lastMs = now;
            return ((now - EPOCH) << (WORKER_BITS + SEQ_BITS)) | (worker << SEQ_BITS) | seq;
        }
    }

    static String describe(long id) {
        long ts = (id >>> (WORKER_BITS + SEQ_BITS)) + EPOCH;
        long worker = (id >>> SEQ_BITS) & ((1L << WORKER_BITS) - 1);
        long seq = id & MAX_SEQ;
        return "ts=" + ts + " worker=" + worker + " seq=" + seq;
    }

    /** Segment allocator: a database row hands out ranges; the app serves ids from memory. */
    static class SegmentStore {
        final AtomicLong maxId = new AtomicLong(0); int roundTrips = 0;
        synchronized long[] allocate(int step) {
            roundTrips++;
            long start = maxId.getAndAdd(step) + 1;
            return new long[] {start, start + step - 1};
        }
    }

    static class SegmentGenerator {
        final SegmentStore store; final int step;
        long cur, end; long[] standby;
        SegmentGenerator(SegmentStore store, int step) {
            this.store = store; this.step = step;
            long[] s = store.allocate(step); cur = s[0]; end = s[1];
        }
        synchronized long next() {
            if (standby == null && cur > end - step * 0.9) {   // 10% consumed: prefetch
                standby = store.allocate(step);
            }
            if (cur > end) {
                if (standby == null) standby = store.allocate(step);
                cur = standby[0]; end = standby[1]; standby = null;
            }
            return cur++;
        }
    }

    public static void main(String[] args) {
        // 1) bit layout
        long[] fake = {EPOCH + 1000};
        Snowflake sf = new Snowflake(37, () -> fake[0]);
        long a = sf.next(), b = sf.next(); fake[0] += 1; long c = sf.next();
        System.out.println(a + "  " + describe(a));
        System.out.println(b + "  " + describe(b));
        System.out.println(c + "  " + describe(c));
        System.out.println("max ids per worker per ms = " + (MAX_SEQ + 1)
            + ", per worker per second = " + (MAX_SEQ + 1) * 1000);
        System.out.println("lifetime of 41 bits = "
            + (1L << 41) / (1000.0 * 3600 * 24 * 365.25) + " years");

        // 2) sequence overflow: the clock advances 1 ms per 5000 reads, faster than 4096 ids per ms
        long[] tick = {0};
        Snowflake busy = new Snowflake(1, () -> EPOCH + (tick[0]++ / 5000));
        long prev = -1; boolean sorted = true;
        for (int i = 0; i < 10_000; i++) { long id = busy.next(); sorted &= id > prev; prev = id; }
        System.out.println("10000 ids, strictly increasing=" + sorted
            + ", overflow waits=" + busy.waits);

        // 3) clock rollback: 3 ms back is absorbed, 40 ms back is refused
        long[] t = {EPOCH + 100};
        Snowflake sf2 = new Snowflake(2, () -> t[0]);
        long x = sf2.next();
        t[0] -= 3; long y = sf2.next();
        System.out.println("after 3 ms rollback: id still increasing = " + (y > x));
        t[0] = EPOCH + 100 - 40;
        try { sf2.next(); } catch (IllegalStateException e) { System.out.println(e.getMessage()); }

        // 4) segment allocator
        SegmentStore store = new SegmentStore();
        SegmentGenerator g = new SegmentGenerator(store, 1000);
        long last = 0; boolean mono = true;
        for (int i = 0; i < 10_500; i++) { long id = g.next(); mono &= id > last; last = id; }
        System.out.println("segment: 10500 ids, last=" + last + ", monotonic=" + mono
            + ", database round trips=" + store.roundTrips);
        // crash: the in-memory remainder of the segment is lost, ids skip but never repeat
        SegmentGenerator g2 = new SegmentGenerator(store, 1000);
        System.out.println("after restart the first id is " + g2.next() + " (gap, no reuse)");
    }
}

import java.util.*;

public class NotifySim {
    enum Priority { HIGH, NORMAL, LOW }

    static final class Msg {
        final String id, dedupKey; final Priority prio; final int createdAt;
        int readyAt, attempts;
        Msg(String id, String dedupKey, Priority prio, int createdAt) {
            this.id = id; this.dedupKey = dedupKey; this.prio = prio;
            this.createdAt = createdAt; this.readyAt = createdAt;
        }
    }

    static final int CAPACITY = 50;             // provider accepts 50 messages per second
    static final double FAIL = 0.20;            // transient provider error rate
    static final int MAX_ATTEMPTS = 5;

    static void run(String mode, boolean priorityAware) {
        Random rnd = new Random(42);
        Comparator<Msg> order = priorityAware
            ? Comparator.<Msg>comparingInt(m -> m.prio.ordinal()).thenComparingInt(m -> m.readyAt)
            : Comparator.<Msg>comparingInt(m -> m.readyAt).thenComparing(m -> m.id);
        PriorityQueue<Msg> ready = new PriorityQueue<>(order);
        List<Msg> waiting = new ArrayList<>();           // retry timers
        Set<String> seen = new HashSet<>();
        List<Integer> highLatency = new ArrayList<>();
        int suppressed = 0, delivered = 0, dead = 0, retries = 0;

        List<Msg> incoming = new ArrayList<>();
        for (int i = 0; i < 2000; i++) {
            incoming.add(new Msg("promo-" + i, "promo:" + i, Priority.LOW, 0));
        }
        for (int s = 0; s < 10; s++)
            for (int i = 0; i < 2; i++)
                incoming.add(new Msg("otp-" + s + "-" + i, "otp:" + s + ":" + i, Priority.HIGH, s));
        for (int i = 0; i < 30; i++)                     // duplicate submissions of existing promos
            incoming.add(new Msg("promo-dup-" + i, "promo:" + i, Priority.LOW, 1));

        int t = 0;
        while (t < 200 && (t < 10 || !ready.isEmpty() || !waiting.isEmpty())) {
            for (Msg m : incoming) {
                if (m.createdAt == t) {
                    if (seen.add(m.dedupKey)) ready.add(m); else suppressed++;
                }
            }
            Iterator<Msg> it = waiting.iterator();
            while (it.hasNext()) {
                Msg m = it.next();
                if (m.readyAt <= t) { it.remove(); ready.add(m); }
            }
            for (int slot = 0; slot < CAPACITY && !ready.isEmpty(); slot++) {
                Msg m = ready.poll();
                m.attempts++;
                if (rnd.nextDouble() < FAIL) {
                    if (m.attempts >= MAX_ATTEMPTS) { dead++; continue; }
                    // exponential backoff with full jitter: uniform in (0, 2^attempts] seconds
                    int backoff = (int) Math.ceil(rnd.nextDouble() * (1 << m.attempts));
                    m.readyAt = t + backoff;
                    waiting.add(m);
                    retries++;
                } else {
                    delivered++;
                    if (m.prio == Priority.HIGH) highLatency.add(t - m.createdAt);
                }
            }
            t++;
        }
        Collections.sort(highLatency);
        System.out.printf("%-26s delivered=%d retries=%d dead=%d duplicates suppressed=%d%n",
            mode, delivered, retries, dead, suppressed);
        System.out.printf("%-26s OTP latency (s): p50=%d max=%d; queue empty at t=%d s%n", "",
            highLatency.get(highLatency.size() / 2), highLatency.get(highLatency.size() - 1), t);
    }

    public static void main(String[] args) {
        System.out.println("2000 promotional + 20 OTP messages + 30 duplicate submissions;");
        System.out.println("provider limit 50/s, 20% transient failures");
        run("single FIFO queue", false);
        run("priority queues (HIGH first)", true);
        double p = Math.pow(FAIL, MAX_ATTEMPTS);
        System.out.printf("probability that one message fails all %d attempts = %.5f%n",
            MAX_ATTEMPTS, p);
    }
}

import java.util.*;

public class FanoutSim {
    public static void main(String[] args) {
        final int users = 100_000, follows = 50;
        Random rnd = new Random(42);
        // popularity weight ~ power law: weight of rank r is r^-0.8
        double[] cum = new double[users];
        double sum = 0;
        for (int r = 0; r < users; r++) { sum += Math.pow(r + 1, -0.8); cum[r] = sum; }
        int[] followers = new int[users];
        int[][] followees = new int[users][];
        for (int u = 0; u < users; u++) {
            Set<Integer> set = new HashSet<>();
            while (set.size() < follows) {
                int v = lowerBound(cum, rnd.nextDouble() * sum);
                if (v != u) set.add(v);
            }
            followees[u] = set.stream().mapToInt(Integer::intValue).toArray();
            for (int v : followees[u]) followers[v]++;
        }
        int max = Arrays.stream(followers).max().getAsInt();
        long edges = (long) users * follows;
        System.out.printf("users=%d follows/user=%d edges=%d max followers=%d%n",
            users, follows, edges, max);
        System.out.println("strategy              inserts/day (1 post each)  lookups per read");
        System.out.printf("fan-out on write      %,12d             %d%n", edges, 1);
        System.out.printf("fan-out on read       %,12d             %d%n", (long) users, follows);
        for (int threshold : new int[] {1000, 5000, 20000}) {
            long writes = 0;
            for (int v = 0; v < users; v++) writes += followers[v] <= threshold ? followers[v] : 0;
            long celebLookups = 0; int celebs = 0;
            for (int v = 0; v < users; v++) if (followers[v] > threshold) celebs++;
            for (int u = 0; u < users; u++)
                for (int v : followees[u]) if (followers[v] > threshold) celebLookups++;
            double perRead = 1 + (double) celebLookups / users;
            System.out.printf("hybrid T=%-6d       %,12d             %.2f   (celebrities=%d)%n",
                threshold, writes, perRead, celebs);
        }
    }

    static int lowerBound(double[] a, double x) {
        int lo = 0, hi = a.length - 1;
        while (lo < hi) { int m = (lo + hi) >>> 1; if (a[m] < x) lo = m + 1; else hi = m; }
        return lo;
    }
}

import java.util.*;

public class ChatSim {
    record Msg(String conv, long seq, String clientMsgId, String body) {}

    /** Server side: one sequencer per conversation; deduplicates by client message id. */
    static class Sequencer {
        private final Map<String, Long> next = new HashMap<>();
        private final Map<String, Msg> byClientId = new HashMap<>();
        Msg accept(String conv, String clientMsgId, String body) {
            Msg dup = byClientId.get(conv + "/" + clientMsgId);
            if (dup != null) return dup;                    // retry of an already stored message
            long seq = next.merge(conv, 1L, Long::sum);
            Msg m = new Msg(conv, seq, clientMsgId, body);
            byClientId.put(conv + "/" + clientMsgId, m);
            return m;
        }
    }

    /** Client side: delivers strictly in sequence order, buffers gaps, ignores duplicates. */
    static class Receiver {
        long lastShown = 0;
        final TreeMap<Long, Msg> pending = new TreeMap<>();
        final List<String> shown = new ArrayList<>();
        void onMessage(Msg m) {
            if (m.seq() <= lastShown || pending.containsKey(m.seq())) {
                shown.add("  (drop duplicate seq " + m.seq() + ")");
                return;
            }
            pending.put(m.seq(), m);
            while (!pending.isEmpty() && pending.firstKey() == lastShown + 1) {
                Msg n = pending.pollFirstEntry().getValue();
                lastShown = n.seq();
                shown.add("show seq " + n.seq() + ": " + n.body());
            }
        }
        long gapFrom() { return pending.isEmpty() ? -1 : lastShown + 1; }
    }

    public static void main(String[] args) {
        Sequencer server = new Sequencer();
        String conv = "c42";
        Msg a = server.accept(conv, "u1-001", "hello");
        Msg b = server.accept(conv, "u2-001", "hi, are you there?");
        Msg c = server.accept(conv, "u1-002", "meeting at 10");
        Msg retry = server.accept(conv, "u1-002", "meeting at 10");   // client retry
        System.out.println("retry returns same seq: " + (retry.seq() == c.seq())
            + " (seq " + retry.seq() + ")");

        Receiver r = new Receiver();
        // network reorders and duplicates: c, a, a, b
        for (Msg m : List.of(c, a, a, b)) {
            r.onMessage(m);
            System.out.println("arrive seq " + m.seq() + " -> pending=" + r.pending.keySet()
                + " lastShown=" + r.lastShown);
        }
        r.shown.forEach(System.out::println);

        Receiver lossy = new Receiver();
        lossy.onMessage(a);
        lossy.onMessage(c);                                           // seq 2 lost
        System.out.println("gap detected, client requests sync from seq " + lossy.gapFrom());
        lossy.onMessage(b);                                           // resync delivers seq 2
        System.out.println("after resync lastShown=" + lossy.lastShown
            + " pending=" + lossy.pending.keySet());
    }
}
